 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 *
 * mqpub 는 한 배치 안에서 키의 끝부분만 비교해, 끝이 같은 메시지를 오류 없이 버린다.
 * 주문번호는 날짜·고정 접미가 공통이라 끝이 겹치므로, 키 맨 끝에 논리 키의 결정적 해시(hex 12자)를 붙여 구별한다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  return `${logical}:${createHash("sha256").update(logical).digest("hex").slice(0, 12)}`;
}

